"""Writes the bench session's simulator scripts (tests/ui/ipodui-p19-bench-*.script).

usage: scripts/bench_sim_script.py          (writes all three)

Sitting 4d's run: the held picks (devbench.h BENCH_R_HELD) have no lines
here; a pick brought back needs its lines again (git history: sitting 4c).

The scripts drive Developer > Bench session > Re-verify the video image
through the real menus (apps/ipodui/devbench_sim.h): every screen of the
runner is a list whose go line, or whose answers, are its last rows, so a
step is "spin to the end, step back to the answer, SELECT".  The order of
the screens here is the runner's (devbench.h bench_reverify_picks and the
table's flags in devbench.c): a step added to the run, or a screen added to
a step, needs a line here, and the script then fails where it desyncs
(bench_sim logs every screen and every SELECT that missed).
"""
import os
import sys

HEADS = {'normal': '# The whole bench session in the simulator: Developer > Bench session >\n# Re-verify the video image, end to end, through the real menus.  The\n# runner, the step table and order, the results file, resume, the\n# auto-skips and the end summary are devbench.c\'s own; only the steps\'\n# device calls are the sim\'s stubs (apps/ipodui/devbench_sim.h says what is\n# modelled and what is real: the job model\'s self-test, the probe image\'s\n# block, the video player).  The two restarts (boot: the display driver;\n# ucop: the UI on the second core) are "reboot" parts; the steps done\n# outside the session are scripted (an album played, Now Playing opened,\n# a video played, the wheel turned), then Bench session > Go on.  Every\n# question gets its normal answer.  Sitting 4d\'s run: the held picks\n# (BENCH_R_HELD: b3, s4b, s4c, vfeed, s7, vbv, vgov) never show.  vplay\n# drops the unit\'s check result (a play before the session wrote one), so\n# its play from Videos runs the first-use check (SIM_VCHECK: the model\n# image counts as one with a clock token): its vck line, about 0.9 s, and\n# the verdict on vplay\'s result line.  The end: bench_sim expect checks\n# the results file: every pick once, with a result, in the picks\' order\n# (devbench.h bench_reverify_picks), the end line and the verified line;\n# no clock150 token (s4c is held; 23693ff4\'s token is already granted);\n# ucop2 passed, so ucop\'s "cop" switch stays for the next start.\n# Generated by scripts/bench_sim_script.py (normal); edit that, not this.\n# needs: video\n# golden: skip\n# log: next start: ui cop (ucop2 pass)\n# env: SIM_VCHECK=1\n# log: unit check: token dropped (bench reset)\n# log: unit check: due (no token)\n# logrange: 600 1500 vck PASS band 11 150 MHz tried 1 (\\d+)ms\n# log: video check: pass 150 MHz\n# nolog: vck INCONCLUSIVE\n# nolog: bench_sim: watchdog\n# timeout: 300\n', 's6fail': '# The bench session\'s clean finish in the simulator: the re-verify run with\n# stage 6\'s row failing (bench_sim set fail_s6, a must-pass step).  The\n# video steps that need it skip by themselves (one "Skipping ahead"\n# screen), the groups that don\'t still run (the second core, its restart\n# and soak), and the session ends: no verified line, no clock150 token,\n# each step once and in order.  The soak fails too (bench_sim set\n# fail_ucop2: a stall), so ucop\'s "cop" switch is taken away: the unit\'s\n# next start runs the build default (the daily driver after the sitting).\n# Generated by scripts/bench_sim_script.py (s6fail); edit that, not this.\n# needs: video\n# golden: skip\n# log: ui switch cleared\n# log: fault switch: ucop2 sees a stall\n# nolog: next start: ui cop\n# nolog: bench_sim: watchdog\n# timeout: 300\n', 'faults': '# The bench session against sitting 4c\'s faults, in the simulator: the\n# normal re-verify run (as ipodui-p19-bench-reverify) with two fault\n# switches set while the visualiser step is outside the session:\n#  - bench_sim set putfail 1: the next results-file open fails, once (the\n#    device\'s lost lines): it is uviz\'s result line, written at Go on;\n#  - bench_sim set lowmem: the probe image\'s block is refused while music\n#    plays (the visualiser\'s album still playing at jvpu).\n# The runner must not lose or run again any step (each step once, in\n# order: 4c bugs a and c), and jvpu must still pass (4c bug b), so the\n# verified line is still earned.  Then, while uck1 is outside, bench_sim\n# set putfails 9: nine opens in a row fail, so three writes are refused at\n# three tries each (FAULT bench put): their lines wait in the RAM queue\n# and go in first, in order, at the next write that opens; none reaches\n# bcmtest.log\'s "bench unsaved:" fallback (the queue holds 8).\n# Generated by scripts/bench_sim_script.py (faults); edit that, not this.\n# needs: video\n# golden: skip\n# log: results file: open refused (fault switch)\n# log: results file: open refused in a row (fault switch)\n# log: FAULT bench put\n# nolog: bench unsaved:\n# nolog: bench_sim: watchdog\n# timeout: 300\n'}
NAMES = {"normal": "reverify", "s6fail": "s6fail", "faults": "faults"}

def go(out, note=""):
    # a start/go screen: the go line is the last; the list doesn't wrap
    out.append(f"wheel +40 10{('          # ' + note) if note else ''}")
    out.append("wait 400")
    out.append("key SELECT")
    out.append("wait 800")

def answer(out, n, a=0, note=""):
    # a question: the n answers are the last rows; answer a
    out.append(f"wheel +40 10{('          # ' + note) if note else ''}")
    out.append("wait 400")
    back = n - 1 - a
    if back:
        out.append(f"wheel -{back} 200")
        out.append("wait 400")
    out.append("key SELECT")
    out.append("wait 800")

def leave_summary(out):
    out.append("key LEFT                # the stopped-session screen: leave")
    out.append("wait 800")

def to_bench(out, playing=False):
    # from the main menu: Settings > About > the developer chord > Bench
    out += ["wheel +20 40            # the last row (Now Playing while music plays)",
            "wait 400",
            ("wheel -2 200            # Settings" if playing else
             "wheel -1 200            # Settings"),
            "wait 400",
            "key SELECT",
            "wait 1200",
            "key SELECT              # About",
            "wait 1500",
            "chord SELECT+LEFT 3200  # Developer",
            "wait 1000",
            "wheel +1 200            # Bench session",
            "wait 400",
            "key SELECT",
            "wait 1200"]

def to_main(out):
    out += ["key LEFT                # out of Developer (a list: LEFT)",
            "wait 800", "key MENU                # About > Settings > Main",
            "wait 800", "key MENU", "wait 800", "key MENU", "wait 800"]

def resume(out, note):
    # the resume question: Go on / Start a new session / Cancel
    answer(out, 3, 0, note)

def manual(out, title, n_answers, outside, a=0, roundtrip=False,
           leaves=False):
    """A manual step: its start screen (leave), the owner's part outside,
    then back: Go on, its question.  leaves: a BENCH_F_LEAVES step (its
    function runs, then a "do it outside" screen before the summary)"""
    out.append(f"# -- {title}")
    go(out, f"{title}: start screen, SELECT: leave")
    if leaves:
        out.append("key LEFT                # the do-it-outside screen: close")
        out.append("wait 800")
    leave_summary(out)
    if roundtrip:
        to_main(out)
    out += outside
    if roundtrip:
        to_bench(out, playing=True)
    else:
        out += ["key SELECT              # Bench session (the Developer menu)",
                "wait 1000"]
    resume(out, f"Go on: {title}")
    answer(out, n_answers, a, f"{title}: the question")

def script(kind):
    o = []
    o.append("bench_sim reset          # no results files, the model's defaults")
    if kind == "normal":
        # a play first, as sitting 4c's left this unit: its check result
        # stored (vcheck.tok), which vplay must drop
        o += ["copy ../../bcmfw/video/vcheck.bin /.rockbox/vcheck.bin",
              "rm_file /.rockbox/.sim_vcheck_band",
              "rm_file /.rockbox/.sim_vcheck_bad",
              "video_start /Misc/S01E03.m4v   # this unit's check result",
              "wait 4000", "video_stop", "wait 500"]
    if kind == "s6fail":
        o.append("bench_sim set fail_s6    # stage 6's row fails (a must-pass step)")
    to_bench(o)
    answer(o, 3, 1, "Re-verify the video image")
    go(o, "the confirm screen: start")
    # pre: done (the flags, no display driver); s05 not needed; boot
    o.append("# -- boot (Display program): the restart")
    go(o, "Display program: start")
    go(o, "Now restart: close")
    leave_summary(o)
    o.append("shot boot_asked")
    o.append("reboot")
    o.append("wait 4000")
    to_bench(o)
    resume(o, "Go on: Display program")
    # jobs: hands off
    go(o, "Hands off now")
    go(o, "Automatic checks done")
    manual(o, "Cover on the chip", 4,
           ["play_files /Music/Square%20Wave%20Quartet/Low%20Frequencies/01%20Hum.mp3",
            "wait 3000                # the album's cover in the panel"])
    if kind == "faults":
        # the open of the next results line fails once: uviz's result line
        # (sitting 4c's lost line); the probe image refused while music
        # plays (sitting 4c's "no probe image" after the visualiser)
        uviz_after = ["bench_sim set putfail 1",
                      "bench_sim set lowmem"]
    else:
        uviz_after = []
    manual(o, "Visualiser on the chip", 4,
           ["play_files /Music/Tone%20Collective/Sine%20Studies/01%20Concert%20A.mp3",
            "wait 1500",
            "wheel +20 40             # Now Playing (the main menu's last row)",
            "wait 400",
            "key SELECT",
            "wait 3000                # the visualiser on the panel",
            "shot uviz_np",
            "key MENU                 # back to the main menu",
            "wait 3000                # the visualiser plays"] + uviz_after,
           roundtrip=True)
    # jvpu, c1: hands off
    go(o, "Hands off now (jvpu, c1)")
    go(o, "Automatic checks done")
    o.append("# -- b13")
    go(o, "Program swap: start")
    answer(o, 3, 0, "b13: No")
    o.append("# -- b5")
    go(o, "Window test: start")
    answer(o, 3, 0, "b5: Yes")
    o.append("# -- s6")
    go(o, "Test clips: start")
    if kind == "s6fail":
        # s6 failed by itself: no question (the row's lines failed it), or
        # the question: the runner asks it after the row
        answer(o, 4, 0, "s6: Smooth, in sync (the row failed)")
        go(o, "Skipping ahead: the video steps (s6's gate), once")
    else:
        answer(o, 4, 0, "s6: Smooth, in sync")
        manual(o, "Play a video", 4,
               ["video_start /Misc/S01E03.m4v   # the player, as Videos plays it",
                "wait 4000                # the check (~0.9 s), then the play",
                "video_stop",
                "wait 500"], leaves=True)
    o.append("# -- ucop: the restart onto the second core")
    go(o, "Screens on second core: start")
    go(o, "Now restart: close")
    leave_summary(o)
    o.append("reboot")
    o.append("wait 4000")
    to_bench(o)
    resume(o, "Go on: Screens on second core")
    manual(o, "Clicks, music stopped", 3, ["wheel +3 200", "wheel -3 200", "wait 500"]
           + (["bench_sim set putfails 9   # three writes in a row refused"]
              if kind == "faults" else []))
    manual(o, "Clicks with music", 3,
           ["play_files /Music/Tone%20Collective/Sine%20Studies/02%20Low%20E.mp3",
            "wait 1000", "wheel +3 200", "wheel -3 200", "wait 500"])
    manual(o, "Scrolling feel", 3, ["wheel +3 100", "wheel -3 100", "wait 500"])
    manual(o, "Panel keeping up", 3, ["wheel +3 100", "wheel -3 100", "wait 500"])
    o.append("audio_stop               # the soak: no track ends in it")
    if kind == "s6fail":
        o.append("bench_sim set fail_ucop2 # the soak sees a stall: ucop2 fails")
    o.append("# -- ucop2: the soak, outside")
    go(o, "Second core, everyday use: start")
    go(o, "Do the rest outside: close")
    leave_summary(o)
    o.append("wait 6000                # the soak (the sim's: 5 s)")
    o.append("key SELECT              # Bench session")
    o.append("wait 1000")
    resume(o, "Go on: Second core, everyday use")
    answer(o, 4, 0, "ucop2: Normal")
    o.append("shot summary")
    o.append("bench_sim dump")
    if kind == "s6fail":
        o.append("bench_sim expect order ended noverified notoken s6=fail "
                 "vplay=autoskip jvpu=pass b5=pass ucop=done ucop2=fail "
                 "nextdefault")
    else:
        o.append("bench_sim expect order ended verified notoken jobs=pass "
                 "jvpu=pass b5=pass s6=pass vplay=pass ucop=done ucop2=pass "
                 "nextcop")
    # out of the summary and Developer (the trace's devmode enter/exit)
    leave_summary(o)
    to_main(o)
    o.append("wait 1000")
    return o

if __name__ == "__main__":
    root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
    for kind, name in NAMES.items():
        path = os.path.join(root, "tests", "ui",
                            "ipodui-p19-bench-%s.script" % name)
        with open(path, "w") as f:
            f.write(HEADS[kind] + "wait 4000\n" + "\n".join(script(kind))
                    + "\n")
        print(os.path.relpath(path, root))
